enum OpnameStatus { draft, completed, cancelled }
class StockOpnameItemModel { const StockOpnameItemModel({required this.productId,required this.productName,required this.sku,required this.unit,required this.systemStock,required this.physicalStock}); final String productId,productName,sku,unit; final int systemStock,physicalStock; int get difference=>physicalStock-systemStock; }
class StockOpnameModel { const StockOpnameModel({required this.id,required this.number,required this.date,required this.warehouseId,required this.warehouseName,required this.status,required this.items,this.notes='' }); final String id,number,warehouseId,warehouseName,notes;final DateTime date;final OpnameStatus status;final List<StockOpnameItemModel> items;int get totalDifference=>items.fold(0,(s,i)=>s+i.difference);StockOpnameModel copyWith({OpnameStatus? status})=>StockOpnameModel(id:id,number:number,date:date,warehouseId:warehouseId,warehouseName:warehouseName,status:status??this.status,items:items,notes:notes);}
